-- ============================================================
-- Seed batch 3: คำถามเชาว์ (brain teaser / riddle category)
-- Safe to re-run (skips duplicates)
-- ============================================================

insert into categories (game_id, name) values
  ('truth-or-lie', 'คำถามเชาว์')
on conflict (game_id, name) do nothing;

with cat as (
  select id, name from categories where game_id = 'truth-or-lie'
)
insert into questions (game_id, category_id, text, answer, explain)
select 'truth-or-lie', cat.id, v.text, v.answer, v.explain
from (values
    ('คำถามเชาว์', 'มีเป็ดยืนเรียงแถว โดยมีเป็ด 2 ตัวอยู่ข้างหน้าเป็ด 2 ตัว มีเป็ด 2 ตัวอยู่ข้างหลังเป็ด 2 ตัว และมีเป็ด 2 ตัวอยู่ตรงกลาง อย่างน้อยต้องมีเป็ดทั้งหมด 6 ตัว', false, 'มั่ว! ใช้เป็ดแค่ 4 ตัวเรียงแถวก็พอ (D1 D2 D3 D4): D1,D2 อยู่หน้า D3,D4 ก็คือ ''2 ตัวหน้า 2 ตัว'', D3,D4 อยู่หลัง D1,D2 ก็คือ ''2 ตัวหลัง 2 ตัว'' และ D2,D3 คือ ''2 ตัวตรงกลาง'' ไม่ต้องมีถึง 6 ตัว'),
    ('คำถามเชาว์', 'มีแค่เดือนกุมภาพันธ์เท่านั้นที่มี 28 วัน', false, 'มั่ว! ทุกเดือนมีอย่างน้อย 28 วันเหมือนกันหมด (เดือนอื่นแค่มีมากกว่า 28 วันขึ้นไป) คำถามคลาสสิกที่หลอกให้คนนึกถึงแค่เดือนกุมภาพันธ์'),
    ('คำถามเชาว์', 'ถ้าคุณกำลังวิ่งแข่งแล้วแซงคนที่อยู่อันดับ 2 ขึ้นไปได้ คุณจะกลายเป็นอันดับ 1', false, 'มั่ว! ถ้าคุณแซงคนอันดับ 2 คุณจะกลายเป็นอันดับ 2 เอง ไม่ใช่อันดับ 1 (อันดับ 1 ยังคงนำอยู่เหมือนเดิม)'),
    ('คำถามเชาว์', 'ก่อนที่มนุษย์จะค้นพบและวัดความสูงของยอดเขาเอเวอเรสต์ ภูเขาที่สูงที่สุดในโลกไม่ใช่เอเวอเรสต์', false, 'มั่ว! เอเวอเรสต์สูงที่สุดในโลกอยู่แล้วโดยธรรมชาติ ไม่ว่ามนุษย์จะค้นพบหรือวัดความสูงได้หรือยัง การค้นพบไม่ได้เปลี่ยนความจริงทางภูมิศาสตร์'),
    ('คำถามเชาว์', 'ชายคนหนึ่งชี้ไปที่รูปถ่ายแล้วพูดว่า ''ผมไม่มีพี่น้องเลย แต่พ่อของชายในรูปคือลูกชายของพ่อผม'' เป็นไปได้ว่าชายในรูปคือลูกชายของเขาเอง', true, 'จริง! ''ลูกชายของพ่อผม'' (โดยไม่มีพี่น้อง) ก็คือตัวเขาเอง ดังนั้นประโยคนี้แปลว่า ''พ่อของชายในรูปคือตัวผมเอง'' นั่นคือชายในรูปเป็นลูกชายของเขา'),
    ('คำถามเชาว์', 'นาฬิกาที่เข็มหยุดเดินไปเลย จะบอกเวลาถูกต้องบ่อยกว่านาฬิกาที่เดินช้าไปวันละ 1 วินาที', true, 'จริง! นาฬิกาที่หยุดสนิทจะตรงเวลาพอดีวันละ 2 ครั้ง แต่นาฬิกาที่เดินช้าไปวันละ 1 วินาทีต้องใช้เวลานานหลายเดือนกว่าจะวนกลับมาตรงอีกครั้ง จึงตรงเวลาน้อยครั้งกว่า'),
    ('คำถามเชาว์', 'เลข 0.999... (เลข 9 ซ้ำไม่รู้จบ) มีค่าเท่ากับ 1 พอดีในทางคณิตศาสตร์', true, 'จริง! แม้จะดูขัดสามัญสำนึก แต่ในทางคณิตศาสตร์ 0.999... ที่มี 9 ต่อกันไม่มีที่สิ้นสุดนั้นมีค่าเท่ากับ 1 เป๊ะ พิสูจน์ได้หลายวิธี เช่น 1/3 = 0.333... ดังนั้น 3/3 = 0.999... = 1'),
    ('คำถามเชาว์', 'ถ้าคุณจุดเทียน 3 เล่ม แล้วลมพัดดับไป 2 เล่ม สุดท้ายคุณจะยังมีเทียนอยู่ทั้งหมด 3 เล่ม (แค่เหลือเล่มที่ติดไฟอยู่ 1 เล่ม)', true, 'จริง! คำถามนี้หลอกให้เข้าใจว่าถามจำนวนเทียนที่ ''เหลือ'' คือจำนวนที่ยังติดไฟ แต่จริงๆ เทียนทั้ง 3 เล่มยังอยู่ครบ เพียงแค่ดับไป 2 เล่มเท่านั้น'),
    ('คำถามเชาว์', 'ในห้องหนึ่งมีชายคนหนึ่งกับเด็กคนหนึ่ง ชายคนนั้นเป็นพ่อของเด็ก แต่เด็กไม่ใช่ ''ลูกชาย'' ของเขา เป็นไปไม่ได้ที่สถานการณ์นี้จะเกิดขึ้นจริง', false, 'มั่ว! เป็นไปได้สบายๆ ถ้าเด็กคนนั้นเป็น ''ลูกสาว'' ไม่ใช่ลูกชาย คำถามนี้หลอกให้คนคิดว่าลูกต้องเป็นลูกชายเท่านั้น'),
    ('คำถามเชาว์', 'ถ้าวันนี้เป็นวันจันทร์ อีก 100 วันข้างหน้าจะเป็นวันจันทร์เช่นกัน', false, 'มั่ว! 100 หารด้วย 7 เหลือเศษ 2 (100 = 7×14 + 2) ดังนั้นอีก 100 วันจะเป็นวันจันทร์ + 2 วัน คือวันพุธ ไม่ใช่วันจันทร์'),
    ('คำถามเชาว์', 'เลข 1 ไม่ถือเป็นทั้งจำนวนเฉพาะและจำนวนประกอบ', true, 'จริง! ตามนิยามทางคณิตศาสตร์ จำนวนเฉพาะต้องมีตัวหารพอดี 2 ตัว (1 กับตัวมันเอง) แต่เลข 1 มีตัวหารแค่ตัวเดียวคือตัวมันเอง จึงไม่เข้าเกณฑ์ทั้งจำนวนเฉพาะและจำนวนประกอบ ถือเป็นกรณีพิเศษ'),
    ('คำถามเชาว์', 'คำว่า ''กก'' ในภาษาไทยเป็นคำที่ไม่มีรูปสระปรากฏให้เห็นเลย', true, 'จริง! คำว่า ''กก'' ประกอบด้วยพยัญชนะ ก ซ้ำกัน 2 ตัว โดยไม่มีรูปสระเขียนกำกับให้เห็น (ออกเสียงเป็นสระโอะที่ไม่ต้องมีรูป) เป็นตัวอย่างคำไทยที่ไม่มีสระปรากฏ'),
    ('คำถามเชาว์', 'เด็กชายและเด็กหญิงคนหนึ่งเกิดวันเดียวกัน เดือนเดียวกัน ปีเดียวกัน จากแม่คนเดียวกัน แต่ทั้งคู่ไม่ใช่ฝาแฝดกัน เป็นไปไม่ได้ที่จะเกิดขึ้นจริง', false, 'มั่ว! เป็นไปได้ถ้าทั้งคู่เป็นส่วนหนึ่งของแฝดสาม (หรือมากกว่า) เช่น คลอดแฝดสามที่มีเด็กชาย 1 คนกับเด็กหญิง 2 คน เด็กชายกับเด็กหญิงคนแรกก็ไม่ถือเป็น ''ฝาแฝด'' กันโดยตรงแต่เกิดวันเดียวกันได้')
  ) as v(cat_name, text, answer, explain)
join cat on cat.name = v.cat_name
where not exists (
  select 1 from questions q2
  where q2.game_id = 'truth-or-lie' and q2.text = v.text
);